// GET /:host/:owner/:repo/:number — Get trail detail
trailRoutes.get(
  "/:host/:owner/:repo/:number",
  describeRoute({
    tags: ["Trails"],
    summary: "Get trail detail",
    responses: {
      200: {
        description: "Trail detail",
        content: {
          "application/json": {
            schema: resolver(
              z.object({
                trail: trailDetailInfoSchema,
                checkpoints: z.array(z.any()),
                has_write_permission: z.boolean(),
              }),
            ),
          },
        },
      },
      404: {
        description: "Trail not found",
        content: { "application/json": { schema: resolver(errorSchema) } },
      },
    },
  }),
  async (c) => {
    const ctx = await resolveTrailWithGitHubContext(c)
    if (ctx instanceof Response) return ctx
    const { db, repo: repoAccess, repoFullName, trail: row, user, githubToken: token } = ctx

    try {
      if (!row.gh_pr_id) {
        try {
          await linkExistingPR(
            db,
            repoFullName,
            repoAccess.id,
            row,
            repoAccess.default_branch || "main",
            token,
          )
        } catch (err) {
          console.error(`Failed to link existing PR for trail #${row.number}:`, err)
        }
      }
      try {
        await resolveAndMaybeSyncActiveTrailBase({
          db,
          repo: repoAccess,
          repoFullName,
          trail: row,
          token,
          sync: true,
        })
      } catch (err) {
        console.error(`Failed to resolve linked PR base for trail #${row.number}:`, err)
      }

      const metadata = trailRowToMetadata(row)
      const [bodyDocument, monitorResults] = await Promise.all([
        ensureTrailBodyDocument(db, row, user.id),
        db.trails.listMonitorResults(row.id),
      ])

      let enrichedCheckpoints: TrailCheckpointSummary[] = []
      if (row.branch) {
        const baseBranch = resolveBaseBranch(row, repoAccess)
        try {
          const dbCheckpoints = await db.checkpoints.getForBranchExcludingBase(
            repoAccess.id,
            row.branch,
            baseBranch,
          )
          enrichedCheckpoints = dbCheckpoints.map(mapCheckpointToTrailSummary)
        } catch {
          // Ignore
        }
      }

      const monitorEnrichment = await getTrailMonitorEnrichment(db, row.id, monitorResults)

      const hasWritePermission = await resolveInstallationWritePermission(c, db, repoAccess)

      const trailInfo: TrailDetailInfo = {
        id: row.id,
        url: trailWebUrl(c, repoAccess, row.number),
        ...metadata,
        phase: trailPhaseForRow(row),
        body_document: bodyDocument,
        priority: metadata.priority ?? "none",
        reviewers: metadata.reviewers ?? [],
        requested_reviewers: metadata.requested_reviewers ?? [],
        comment_count: row.comment_count,
        unresolved_count: row.unresolved_count,
        checkpoint_count: enrichedCheckpoints.length,
        has_code_changes: row.has_code_changes,
        monitors: monitorResults.map((monitor) => ({
          key: monitor.key,
          label: monitor.label,
          value_type: monitor.value_type,
          percent_value: monitor.percent_value,
          size_value: monitor.size_value,
          boolean_value: monitor.boolean_value,
          rationale: monitor.rationale,
          polarity: monitor.polarity,
          trend_delta: monitorEnrichment.get(monitor.key)?.trendDelta ?? null,
          evaluating: monitorEnrichment.get(monitor.key)?.evaluating ?? false,
          history: monitorEnrichment.get(monitor.key)?.history ?? [
            {
              percent_value: monitor.percent_value,
              size_value: monitor.size_value,
              boolean_value: monitor.boolean_value,
              rationale: monitor.rationale,
              evaluating: false,
              run_id: monitor.run_id,
              head_sha: monitor.head_sha,
              updated_at: monitor.updated_at,
            },
          ],
          run_id: monitor.run_id,
          head_sha: monitor.head_sha,
          updated_at: monitor.updated_at,
        })),
      }

      return c.json({
        trail: trailInfo,
        checkpoints: enrichedCheckpoints,
        has_write_permission: hasWritePermission,
      })
    } catch (err) {
      if (isGitHubAuthError(err)) {
        return c.json({ error: "GitHub token expired" }, 401)
      }
      console.error(`Failed to fetch trail ${row.number}:`, err)
      recordSpanError(err)
      return c.json({ error: "Failed to fetch trail" }, 500)
    }
  },
)

// GET /:host/:owner/:repo/:number/definitions — Repo-authored definitions used by this trail.
trailRoutes.get(
  "/:host/:owner/:repo/:number/definitions",
  describeRoute({
    tags: ["Trails"],
    summary: "Get trail monitor and gate definitions",
    responses: {
      200: {
        description: "Trail definitions",
        content: { "application/json": { schema: resolver(trailDefinitionsResponseSchema) } },
      },
      403: {
        description: "Repository membership required",
        content: { "application/json": { schema: resolver(errorSchema) } },
      },
      404: {
        description: "Trail not found",
        content: { "application/json": { schema: resolver(errorSchema) } },
      },
    },
  }),
  async (c) => {
    const ctx = await resolveTrailWithUserContext(c)
    if (ctx instanceof Response) return ctx
    const membershipError = requireRepoMembership(c, ctx)
    if (membershipError) return membershipError

    const { db, repo: repoAccess, repoFullName, user } = ctx

    // ENT-1174: flag-on reads this from the cell instead of MySQL/GitHub —
    // repo-scoped (no trail number), a deliberate shape delta from this
    // local route (ledger §13.1). Placed AFTER requireRepoMembership (no
    // cell equivalent to that specific local gate) so a membership failure
    // behaves identically either way. See
    // maybeTrailsCellTrailDefinitionsRead's doc comment: it bails to null
    // (falling through to the local body below) whenever the cell's
    // monitor_definitions comes back empty, since this cell build can never
    // supply GitHub-backed monitor definitions yet (ENT-1180) and serving an
    // empty array as authoritative would silently drop a flag-on user's
    // pending-monitor cards.
    const cell = await maybeTrailsCellTrailDefinitionsRead(c, ctx)
    if (cell) return cell

    try {
      const configRef = repoAccess.default_branch || RUNNER_CONFIG_REF
      const monitorCacheKey = trailMonitorDefinitionsCacheKey(repoAccess.id, configRef)
      const cachedMonitorDefinitions = await readTrailMonitorDefinitionsCache(
        c.env.ENTIRE_CACHE,
        monitorCacheKey,
      )
      const monitorDefinitionsPromise = cachedMonitorDefinitions
        ? Promise.resolve(cachedMonitorDefinitions.monitorDefinitions)
        : (async () => {
            const token = await getGitHubTokenForRepoRequest(c, db, user.id, repoAccess)
            if (!token) return c.json({ error: "GitHub token required" }, 401)

            const result = await fetchAndCacheTrailRunnerDefinitions({
              cache: c.env.ENTIRE_CACHE,
              key: monitorCacheKey,
              repoFullName,
              ref: configRef,
              token,
            })
            return result.monitorDefinitions
          })()

      if (cachedMonitorDefinitions && !cachedMonitorDefinitions.fresh) {
        refreshTrailMonitorDefinitionsCacheInBackground(c, {
          cache: c.env.ENTIRE_CACHE,
          key: monitorCacheKey,
          db,
          userId: user.id,
          repo: repoAccess,
          repoFullName,
          ref: configRef,
        })
      }

      const gatesEnabledPromise = trailGatesEnabledForRepo(c.env, repoAccess)
      const gateDefinitionsPromise = gatesEnabledPromise.then(async (gatesEnabled) => {
        if (!gatesEnabled) return []
        await db.gates.ensureBuiltinDefinitions(repoAccess.id, user.id)
        const rows = await db.gates.listDefinitions(repoAccess.id)
        return rows.map(serializeGateDefinition)
      })
      const [monitorDefinitions, gateDefinitions, gatesEnabled] = await Promise.all([
        monitorDefinitionsPromise,
        gateDefinitionsPromise,
        gatesEnabledPromise,
      ])
      if (monitorDefinitions instanceof Response) return monitorDefinitions

      return c.json({
        monitor_definitions: monitorDefinitions,
        gate_definitions: gateDefinitions,
        gates_enabled: gatesEnabled,
      })
    } catch (err) {
      if (isGitHubAuthError(err)) {
        return c.json({ error: "GitHub token expired" }, 401)
      }
      console.error(`Failed to fetch trail definitions for trail ${ctx.trail.number}:`, err)
      recordSpanError(err)
      return c.json({ error: "Failed to fetch trail definitions" }, 500)
    }
  },
)

// GET /:host/:owner/:repo/:number/contributors — Get trail contributors
trailRoutes.get(
  "/:host/:owner/:repo/:number/contributors",
  describeRoute({
    tags: ["Trails"],
    summary: "Get trail contributors",
    responses: {
      200: {
        description: "Trail contributors",
        content: {
          "application/json": {
            schema: resolver(trailContributorsResponseSchema),
          },
        },
      },
      404: {
          const result = await startTrailConfiguredRun({
            env: c.env,
            db,
            repo: repoAccess,
            repoFullName,
            trail: row,
            runnerId: reviewRunnerId,
            githubToken: token,
            actorId: userId,
            triggerType: "push",
            configRef,
            skipCompletedReview: true,
          })
          if (result.kind === "spawned") launched += 1
        } catch (err) {
          if (err instanceof TrailConfiguredRunUnavailableError) {
            unavailableReason = err.reason
            continue
          }
          throw err
        }
      }

      if (unavailableReason !== null) {
        return c.json({ error: unavailableReason }, 422)
      }

      runInBackground(c, () => requestTrailGateEvaluation(c.env, repoAccess.id, row.id))
      return c.json({ launched })
    } catch (err) {
      if (isGitHubAuthError(err)) {
        return c.json({ error: "GitHub token expired" }, 401)
      }
      console.error(`Failed to re-run review for trail ${row.number}:`, err)
      recordSpanError(err)
      return c.json({ error: "Failed to re-run review" }, 500)
    }
  },
)

// GET /:host/:owner/:repo/:number/runs/:runnerId — Fetch latest Trail runner result
trailRoutes.get(
  "/:host/:owner/:repo/:number/runs/:runnerId",
