import type { Env } from "../../env"
import { getDb } from "../db"
import type { Repo } from "../db/repos"
import { branchCodeBeyondBaseStatus, resolveBranchTipSha } from "../git-source"
import { checkBranchExists } from "../github"
import { cancelRun } from "../sandbox-runs/service"
import type { SandboxRun } from "../sandbox-runs/types"
import { errorString } from "../telemetry"
import { getInstallationToken } from "../token"
import {
  startTrailConfiguredRun,
  TrailConfiguredRunUnavailableError,
} from "../trail-runner-launcher"
import {
  fetchRunnerConfigs,
  isPushTriggeredReviewRunnerConfig,
  normalizeRunnerConfig,
  type NormalizedRunnerConfig,
  type RunnerConfigFile,
} from "./config-loader"

function normalizeRunnerConfigs(configs: RunnerConfigFile[]): NormalizedRunnerConfig[] {
  return configs.flatMap((config) => {
    try {
      return [normalizeRunnerConfig(config)]
    } catch (error) {
      console.warn("[push-router] skipping unsupported runner config", {
        runnerId: config.id,
        error: errorString(error),
      })
      return []
    }
  })
}

function hasFirstClassTrailOutput(config: NormalizedRunnerConfig): boolean {
  return !!config.output?.trailMonitor || config.output?.trailField === "body"
}

function isPushTriggeredTrailPromptConfig(config: NormalizedRunnerConfig): boolean {
  return (
    config.enabled &&
    config.scope === "trail" &&
    config.triggerTypes.includes("push") &&
    config.automationKind === "trail_prompt" &&
    !config.trailsReviewEnabled &&
    hasFirstClassTrailOutput(config)
  )
}

function trailForConfiguredRun(
  repo: Repo,
  branch: string,
  trail: {
    id: string
    repo_id?: string | null
    branch?: string | null
    head_sha?: string | null
    gh_pr_id: number | null
    base?: string | null
    status?: string | null
  },
): Parameters<typeof startTrailConfiguredRun>[0]["trail"] {
  return {
    id: trail.id,
    branch: trail.branch ?? branch,
    head_sha: trail.head_sha ?? null,
    gh_pr_id: trail.gh_pr_id,
    repo_id: trail.repo_id ?? repo.id,
    base: trail.base ?? null,
    status: trail.status ?? null,
  }
}

type PushTrailContext = {
  id: string
  repo_id?: string | null
  branch?: string | null
  head_sha?: string | null
  gh_pr_id: number | null
  base?: string | null
  status?: string | null
}

type LaunchPushRunnersArgs = {
  env: Env
  repo: Repo
  repoFullName: string
  trail: PushTrailContext
  commitSha: string
  branch: string
  token: string
  rawConfigs: RunnerConfigFile[]
}

type LaunchPushTriggeredRunsArgs = {
  env: Env
  repo: Repo
  repoFullName: string
  trail: PushTrailContext
  commitSha: string
  branch: string
  token: string
}

class PushRunnersLaunchError extends Error {
  constructor(
    message: string,
    readonly launchedRuns: SandboxRun[],
    readonly originalError: unknown,
  ) {
    super(message)
    this.name = "PushRunnersLaunchError"
  }
}

async function launchPushRunners(
  args: LaunchPushRunnersArgs,
  matches: (config: NormalizedRunnerConfig) => boolean,
  logLabel: "review" | "trail_prompt",
): Promise<SandboxRun[]> {
  const runnerConfigs = normalizeRunnerConfigs(args.rawConfigs).filter(matches)
  if (runnerConfigs.length === 0) return []

  const db = getDb(args.env)
  const configRef = args.repo.default_branch ?? "main"
  const trail = trailForConfiguredRun(args.repo, args.branch, args.trail)
  const settled = await Promise.allSettled(
    runnerConfigs.map(async (runnerConfig): Promise<SandboxRun | null> => {
      try {
        const result = await startTrailConfiguredRun({
          env: args.env,
          db,
          repo: args.repo,
          repoFullName: args.repoFullName,
          trail,
          runnerId: runnerConfig.id,
          githubToken: args.token,
          triggerType: "push",
          commitSha: args.commitSha,
          configRef,
        })
        return result.kind === "spawned" ? result.run : null
      } catch (error) {
        if (error instanceof TrailConfiguredRunUnavailableError) {
          console.warn(`[push-router] ${logLabel} runner unavailable`, {
            runnerId: runnerConfig.id,
            trailId: args.trail.id,
            reason: error.reason,
          })
          return null
        }
        throw error
      }
    }),
  )
  // Collect every run that DID spawn before surfacing a sibling's failure. With
  // fanout, a plain Promise.all would reject on the first throw and discard the
  // handles of runs that already spawned — stranding them outside the caller's
  // stale-push cleanup (which cancels via the returned handles). Mirror the
  // event-triggered path: carry the partial launches on the thrown error.
  const launched = settled.flatMap((result) =>
    result.status === "fulfilled" && result.value ? [result.value] : [],
  )
  const failed = settled.find((result) => result.status === "rejected")
  if (failed?.status === "rejected") {
    throw new PushRunnersLaunchError(`${logLabel} runner fanout failed`, launched, failed.reason)
  }
  return launched
}

async function launchTrailsReviewPushRunners(args: LaunchPushRunnersArgs): Promise<SandboxRun[]> {
  return launchPushRunners(args, isPushTriggeredReviewRunnerConfig, "review")
}

async function launchTrailPromptPushRunners(args: LaunchPushRunnersArgs): Promise<SandboxRun[]> {
  return launchPushRunners(args, isPushTriggeredTrailPromptConfig, "trail_prompt")
}

function isEventTriggeredTrailConfig(
  config: NormalizedRunnerConfig,
  triggerType: "checks_failed" | "merge_conflict",
): boolean {
  return (
    config.enabled &&
    config.scope === "trail" &&
    config.triggerTypes.includes(triggerType) &&
    (config.automationKind === "trail_prompt" ||
      (triggerType === "checks_failed" && config.automationKind === "fix_ci"))
  )
}

class EventTriggeredRunsLaunchError extends Error {
  constructor(
    message: string,
    readonly launchedRuns: SandboxRun[],
    readonly originalError: unknown,
  ) {
    super(message)
    this.name = "EventTriggeredRunsLaunchError"
  }
}

export async function launchEventTriggeredRunsForTrail(args: {
  env: Env
  repo: Repo
  repoFullName: string
  trail: PushTrailContext
  commitSha: string
  branch: string
  token: string
  triggerType: "checks_failed" | "merge_conflict"
  baseSha?: string | null
  rawConfigs?: RunnerConfigFile[]
}): Promise<SandboxRun[]> {
  const rawConfigs =
    args.rawConfigs ??
    (await fetchRunnerConfigs(args.repoFullName, args.repo.default_branch ?? "main", args.token))
  const configs = normalizeRunnerConfigs(rawConfigs).filter((config) =>
    isEventTriggeredTrailConfig(config, args.triggerType),
  )
  if (configs.length === 0) return []

  const db = getDb(args.env)
  const configRef = args.repo.default_branch ?? "main"
  const trail = trailForConfiguredRun(args.repo, args.branch, args.trail)
  const settled = await Promise.allSettled(
    configs.map(async (config): Promise<SandboxRun | null> => {
      try {
        const result = await startTrailConfiguredRun({
          env: args.env,
          db,
          repo: args.repo,
          repoFullName: args.repoFullName,
          trail,
          runnerId: config.id,
          githubToken: args.token,
          triggerType: args.triggerType,
          commitSha: args.commitSha,
          baseSha: args.baseSha,
          configRef,
          // Failed-check webhooks are trusted GitHub App events. Their guarded
          // pushes use the installation identity rather than borrowing a Trail
          // author's permission.
          ...(args.triggerType === "checks_failed" && config.gitPush
            ? { gitPushAuthorized: true }
            : {}),
        })
        return result.kind === "spawned" ? result.run : null
      } catch (error) {
        if (error instanceof TrailConfiguredRunUnavailableError && !error.outcomeRecorded) {
          console.warn(`[event-router] ${args.triggerType} runner unavailable`, {
            runnerId: config.id,
            trailId: args.trail.id,
            reason: error.reason,
          })
          return null
        }
        throw error
      }
    }),
  )
  const launched = settled.flatMap((result) =>
    result.status === "fulfilled" && result.value ? [result.value] : [],
  )
  const failed = settled.find((result) => result.status === "rejected")
  if (failed?.status === "rejected") {
    throw new EventTriggeredRunsLaunchError(
      `${args.triggerType} runner fanout failed`,
      launched,
      failed.reason,
    )
  }
  return launched
}

