  repoFullName,
  trail,
  commitSha,
  branch,
  token,
}: LaunchPushTriggeredRunsArgs): Promise<void> {
  // Skip auto-runs while the branch has no commits beyond base — there's nothing
  // for runners to evaluate. (A squash-merged branch that still has distinct
  // commits is "has_code", so its legitimate stale-push run still launches.) An
  // "unknown" compare (missing ref or a transient git-source error) proceeds:
  // fail open so GitHub instability doesn't silently suppress legitimate runs,
  // matching the merged/closed checkBranchExists path; the queue's fail-fast
  // handling backstops a branch that's genuinely gone.
  const base = trail.base ?? repo.default_branch ?? "main"
  const codeStatus = await branchCodeBeyondBaseStatus(
    env,
    { accessToken: token, repoFullName },
    base,
    branch,
  )
  if (codeStatus === "no_code") {
    console.log("[push-router] skipping auto-run: branch has no commits beyond base", {
      repo: repoFullName,
      branch,
      trailId: trail.id,
    })
    return
  }

  // SECURITY: Load configs from the default branch, not the pushed/PR commit.
  // This prevents a branch author from injecting malicious runner commands.
  const defaultBranch = repo.default_branch ?? "main"
  const rawConfigs = await fetchRunnerConfigs(repoFullName, defaultBranch, token)
  const pushArgs: LaunchPushRunnersArgs = {
    env,
    repo,
    repoFullName,
    trail,
    commitSha,
    branch,
    token,
    rawConfigs: rawConfigs,
  }
  // Capture the runs this push launches for `commitSha` so we can tear them down again
  // if it turns out this push is not the branch tip (see the stale-push branch below).
  const launched: SandboxRun[] = []
  let deferredLaunchError: unknown = null
  try {
    launched.push(...(await launchTrailPromptPushRunners(pushArgs)))
    launched.push(...(await launchTrailsReviewPushRunners(pushArgs)))
  } catch (error) {
    if (error instanceof PushRunnersLaunchError) {
      launched.push(...error.launchedRuns)
      deferredLaunchError = error.originalError
    } else {
      deferredLaunchError = error
    }
  }
  try {
    launched.push(
      ...(await launchEventTriggeredRunsForTrail({
        ...pushArgs,
        triggerType: "merge_conflict",
      })),
    )
  } catch (error) {
    if (error instanceof EventTriggeredRunsLaunchError) {
      launched.push(...error.launchedRuns)
      deferredLaunchError ??= error.originalError
    } else {
      deferredLaunchError ??= error
    }
  }

  // A newer commit supersedes the still-active runs left on older commits for this
  // trail. Cancel them only AFTER the replacements are launched: fetchRunnerConfigs
  // and the launches can throw on transient GitHub errors, and cancelling first would
  // leave the trail with its in-progress runs canceled and nothing running — this
  // function is intentionally fail-open.
  const db = getDb(env)
  const superseded = await db.sandboxRuns.listSupersededRunsForTrail({
    trailId: trail.id,
    currentHeadSha: commitSha,
  })

  // Nothing to cancel on either branch below, so skip the git-source tip round-trip.
  if (launched.length === 0 && superseded.length === 0) {
    if (deferredLaunchError) throw deferredLaunchError
    return
  }

  // Resolve the branch tip AFTER snapshotting the runs above, never before. The check
  // can't be made atomic with the cancellation, so this ordering is what keeps a
  // concurrent push from mutually cancelling:
  //
  //   - A stale, redelivered, or out-of-order push carries an older commitSha; its tip
  //     resolves to a newer sha, so it never tears down the newer commit's runs.
  //   - A concurrent newer push for commit Y can race this handler. If Y's runs are
  //     already in `superseded`, Y had already advanced the branch tip before those runs
  //     were written, so this resolve (taken after the snapshot) sees tip == Y != commitSha.
  //     If Y launches its runs after the snapshot, they aren't in `superseded` and so can't
  //     be cancelled. Either way Y's freshly-launched runs survive.
  //
  // On an unknown tip (transient git-source error) skip all cancellation rather than risk
  // tearing down fresh runs.
  //
  // Resolve against the authoritative source, never the go-git-api mirror: the mirror is
  // reconciled asynchronously, so right after a push it can still report the pre-push tip.
  // A stale tip here would make a stale push look like the branch tip and cancel the newest
  // commit's freshly-launched runs as "superseded" — the exact data loss this guards against.
  const tipSha = await resolveBranchTipSha(
    env,
    { accessToken: token, repoFullName, requireAuthoritative: true },
    branch,
  )
  if (tipSha === null) {
    if (deferredLaunchError) throw deferredLaunchError
    return
  }

  if (tipSha === commitSha) {
    // This push is the branch tip: tear down the runs left on the superseded commits.
    await cancelRuns(env, db, trail.id, superseded)
    if (deferredLaunchError) throw deferredLaunchError
    return
  }

  // tipSha !== commitSha: the branch has already advanced past this push's commit, so the
  // runs we just launched are for a superseded commit. Cancel our OWN launched runs — not
  // `superseded`, which may include the newer commit's runs that must survive. Without this
  // a stale push processed out of order leaves a zombie run whose later created_at would let
  // applyTrailOutput's write-time guard pick its stale output over the newer commit's.
  await cancelRuns(env, db, trail.id, launched)
}

async function cancelRuns(
  env: Env,
  db: ReturnType<typeof getDb>,
  trailId: string,
  runs: SandboxRun[],
): Promise<void> {
  await Promise.allSettled(
    runs.map(async (run) => {
      try {
        await cancelRun(env, db, run)
      } catch (error) {
        console.warn("[push-router] failed to cancel superseded run", {
          trailId,
          runId: run.id,
          error: error instanceof Error ? error.message : String(error),
        })
      }
    }),
  )
}

function getSameRepoPullRequestContext(payload: Record<string, unknown>): {
  repoGithubId: number
  repoFullName: string | null
  branch: string
  commitSha: string
  prNumber: number
} | null {
  const repoPayload = payload.repository as { id?: unknown; full_name?: unknown } | undefined
  if (typeof repoPayload?.id !== "number") return null

  const pr = payload.pull_request as Record<string, unknown> | undefined
  if (!pr) return null

  // Match the sibling PR handlers: a draft opened-as-draft has no trail yet and
  // shouldn't trigger runs (covers the CI shadow draft PR too).
  if (pr.draft === true) return null

  const prNumber = typeof pr.number === "number" ? pr.number : null
  const head = pr.head as Record<string, unknown> | undefined
  const base = pr.base as Record<string, unknown> | undefined
  const branch = typeof head?.ref === "string" ? head.ref : null
  const commitSha = typeof head?.sha === "string" ? head.sha : null
  const headRepo = head?.repo as { id?: unknown } | undefined
  const baseRepo = base?.repo as { id?: unknown } | undefined

  if (!prNumber || !branch || !commitSha) return null
  if (typeof headRepo?.id !== "number" || typeof baseRepo?.id !== "number") return null
  if (headRepo.id !== baseRepo.id) return null

  return {
    repoGithubId: repoPayload.id,
    repoFullName: typeof repoPayload.full_name === "string" ? repoPayload.full_name : null,
    branch,
    commitSha,
    prNumber,
  }
}

export async function handleTrailOpenedAutoRuns(args: {
  env: Env
  repo: Repo
  repoFullName: string
  trail: PushTrailContext
  commitSha: string | null
  githubToken: string
}): Promise<void> {
  const { env, repo, repoFullName, trail, commitSha, githubToken } = args
  if (!repo.trails_enabled || !repo.runners_enabled || !repo.auto_run_on_push) return
  if (!trail.branch || !commitSha) return
  if (trail.status === "merged" || trail.status === "closed") return

  // The "has code beyond base" gate lives in launchPushTriggeredRunsForTrail.
  await launchPushTriggeredRunsForTrail({
    env,
    repo,
    repoFullName,
    trail,
    commitSha,
    branch: trail.branch,
    token: githubToken,
  })
}

export async function handlePullRequestAutoRuns(
  payload: Record<string, unknown>,
  action: string | null,
  env: Env,
): Promise<void> {
  if (action !== "opened" && action !== "ready_for_review") return

  const installation = payload.installation as { id?: number } | undefined
  if (!installation?.id) return

  const prContext = getSameRepoPullRequestContext(payload)
  if (!prContext) return

  const db = getDb(env)
  const repo = await db.repos.getByGithubId(prContext.repoGithubId)
  if (!repo || !repo.trails_enabled || !repo.runners_enabled || !repo.auto_run_on_push) return

  const dbInstallationId = await db.installations.findIdByGitHubId(installation.id)
  if (!dbInstallationId || repo.installation_id !== dbInstallationId) return

  const repoFullName = repo.full_name ?? prContext.repoFullName
  if (!repoFullName) return

  const trailRow = await db.trails.getByBranch(repo.id, prContext.branch)
  if (!trailRow) return

  const token = await getInstallationToken(
    installation.id,
    {
      appId: env.GITHUB_CLIENT_ID,
      privateKey: env.GITHUB_APP_PRIVATE_KEY,
    },
    env.ENTIRE_CACHE,
  )
  if (!token) {
    throw new Error("Failed to fetch GitHub installation token for PR auto-run")
  }

  // gh_pr_id is normally already linked by processTrailGhPrIdLinkOnPROpened;
  // fall back to the PR number from the payload so the runner prompt has it.
  await handleTrailOpenedAutoRuns({
    env,
    repo,
    repoFullName,
    trail: { ...trailRow, gh_pr_id: trailRow.gh_pr_id ?? prContext.prNumber },
    commitSha: prContext.commitSha,
    githubToken: token,
  })
}

export async function handleBasePushMergeConflictAutoRuns(
  payload: Record<string, unknown>,
  env: Env,
): Promise<void> {
  const ref = payload.ref as string | undefined
  if (!ref?.startsWith("refs/heads/") || payload.deleted === true) return
  if (typeof payload.after !== "string" || !payload.after) return

  const installation = payload.installation as { id?: number } | undefined
  const repoPayload = payload.repository as { id?: number; full_name?: string } | undefined
  if (!installation?.id || !repoPayload?.id) return

  const db = getDb(env)
  const repo = await db.repos.getByGithubId(repoPayload.id)
  if (!repo || !repo.trails_enabled || !repo.runners_enabled || !repo.auto_run_on_push) return
  const repoFullName = repo.full_name ?? repoPayload.full_name
  if (!repoFullName) return

  const pushedBranch = ref.replace("refs/heads/", "")
  const eventBaseSha = (payload.after as string).toLowerCase()
  const defaultBranch = repo.default_branch ?? "main"
  const impacted = await db.trails.listOpenTrailsForBranchImpact(
    repo.id,
    pushedBranch,
    defaultBranch,
  )
  // Head-branch pushes are handled by handlePushAutoRuns. This path is only
  // for trails whose base moved.
  const baseImpactedIds = impacted
    .filter(
      (trail) => trail.branch !== pushedBranch && (trail.base || defaultBranch) === pushedBranch,
    )
    .map((trail) => trail.id)
  if (baseImpactedIds.length === 0) return

  const token = await getInstallationToken(
    installation.id,
    { appId: env.GITHUB_CLIENT_ID, privateKey: env.GITHUB_APP_PRIVATE_KEY },
    env.ENTIRE_CACHE,
  )
  if (!token) throw new Error("Failed to fetch GitHub installation token for merge_conflict")

  // Drop delayed/out-of-order base deliveries before they can create a run
  // whose later creation time would make obsolete work look newest.
  const baseTipBefore = await resolveBranchTipSha(
    env,
    { accessToken: token, repoFullName, requireAuthoritative: true },
    pushedBranch,
  )
  if (!baseTipBefore || baseTipBefore.toLowerCase() !== eventBaseSha) return

  const rawConfigs = await fetchRunnerConfigs(repoFullName, defaultBranch, token)
  const trails = await db.trails.getByIds(repo.id, baseImpactedIds)
  const launchedGroups = (
    await Promise.all(
      trails.map(async (trail) => {
        if (!trail.branch || trail.status !== "open") return null
        const headSha = await resolveBranchTipSha(
          env,
          { accessToken: token, repoFullName, requireAuthoritative: true },
          trail.branch,
        )
        if (!headSha) return null
        try {
          const runs = await launchEventTriggeredRunsForTrail({
            env,
            repo,
            repoFullName,
            trail,
            commitSha: headSha,
            branch: trail.branch,
            token,
            triggerType: "merge_conflict",
            baseSha: eventBaseSha,
            rawConfigs,
          })
          return { trailId: trail.id, branch: trail.branch, headSha, runs, error: null }
        } catch (error) {
          const runs = error instanceof EventTriggeredRunsLaunchError ? error.launchedRuns : []
          const originalError =
            error instanceof EventTriggeredRunsLaunchError ? error.originalError : error
          return {
            trailId: trail.id,
            branch: trail.branch,
            headSha,
            runs,
            error: originalError,
          }
        }
      }),
    )
  ).filter((group): group is NonNullable<typeof group> => group !== null)
  const launchError = launchedGroups.find((group) => group.error)?.error

  if (launchedGroups.every((group) => group.runs.length === 0)) {
    if (launchError) throw launchError
    return
  }

  // Revalidate after all fallible launch work. If either side moved while the
  // candidates were being created, cancel only the runs from this delivery.
  const baseTipAfter = await resolveBranchTipSha(
    env,
    { accessToken: token, repoFullName, requireAuthoritative: true },
    pushedBranch,
  )
  if (baseTipAfter && baseTipAfter.toLowerCase() !== eventBaseSha) {
    await Promise.all(launchedGroups.map((group) => cancelRuns(env, db, group.trailId, group.runs)))
    return
  }

  await Promise.all(
    launchedGroups.map(async (group) => {
      const currentHead = await resolveBranchTipSha(
        env,
        { accessToken: token, repoFullName, requireAuthoritative: true },
        group.branch,
      )
      if (currentHead && currentHead.toLowerCase() !== group.headSha.toLowerCase()) {
        await cancelRuns(env, db, group.trailId, group.runs)
      }
    }),
  )
  if (launchError) throw launchError
}

