runnerRoutes.patch("/repos/:repoId/runner-settings", async (c) => {
  const userId = c.get("userId")
  const repoId = c.req.param("repoId")
  const db = getDb(c.env)

  try {
    await db.repos.requireRepoAccess(userId, repoId)
  } catch {
    return c.json({ error: "Repository not found" }, 404)
  }

  const repo = await db.repos.getById(repoId)
  if (!repo) {
    return c.json({ error: "Repository not found" }, 404)
  }

  const body = await c.req
    .json<{
      runners_enabled?: boolean
      auto_run_on_push?: boolean
    }>()
    .catch(() => null)

  if (!body || (body.runners_enabled === undefined && body.auto_run_on_push === undefined)) {
    return c.json({ error: "At least one setting is required" }, 400)
  }

  const normalizedAutoRunOnPush =
    body.runners_enabled === false && body.auto_run_on_push === undefined
      ? false
      : body.auto_run_on_push

  const nextRunnersEnabled = body.runners_enabled ?? repo.runners_enabled
  const nextAutoRunOnPush = normalizedAutoRunOnPush ?? repo.auto_run_on_push
  if (nextAutoRunOnPush && !nextRunnersEnabled) {
    return c.json({ error: "auto_run_on_push requires runners_enabled" }, 400)
  }

  const updatedRepo = await db.repos.updateRunnerSettings(repoId, {
    runners_enabled: body.runners_enabled,
    auto_run_on_push: normalizedAutoRunOnPush,
  })

  return c.json({
    settings: {
      runners_enabled: updatedRepo.runners_enabled,
      auto_run_on_push: updatedRepo.auto_run_on_push,
    },
  })
})

