			if len(args) == 1 {
				selector = args[0]
			}
			// Delegates to the shared trail-review resolver so number/id/branch
			// selectors and insecure-HTTP handling stay in one place.
			return runTrailReviewWatch(cmd, selector, jsonOutput, showPings, once)
		},
	}

