// Toggle repo agent-runner settings (runners_enabled / auto_run_on_push).
//
// owner/repo-keyed sibling of the legacy UUID-keyed
// `PATCH /repos/:repoId/runner-settings` (api/src/routes/runners.ts), which
// stays in place serving the PlanetScale path until PlanetScale is dropped.
// owner/repo keying lets the dual-write mirror feed resolveCell directly — no
// UUID→ULID bridge. PlanetScale stays authoritative; the entire-api write is a
// best-effort mirror behind the entire-api flag. Gate matches the
// legacy route: trails feature flag + repo membership (no GitHub-admin check,
// unlike the public-sharing route above).
repoRoutes.patch(
  "/:org/:repo/settings/runner-settings",
  describeRoute({
    tags: ["Repo Settings"],
    summary: "Update repo agent-runner settings",
    description:
      "Updates `repos.runners_enabled` / `repos.auto_run_on_push`. Requires the " +
      "caller to have the trails feature flag and access to the repo. " +
      "`auto_run_on_push` requires `runners_enabled`.",
    requestBody: {
      required: true,
      content: {
        "application/json": { schema: runnerSettingsRequestBodySchema },
      },
    },
    responses: {
      200: {
        description: "New settings values",
        content: {
          "application/json": { schema: resolver(runnerSettingsResponseSchema) },
        },
      },
      400: {
        description: "Invalid body",
        content: { "application/json": { schema: resolver(repoSettingsErrorSchema) } },
      },
      404: {
        description: "Repository not found",
        content: { "application/json": { schema: resolver(repoSettingsErrorSchema) } },
      },
      500: {
        description: "Failed to update settings",
        content: { "application/json": { schema: resolver(repoSettingsErrorSchema) } },
      },
    },
  }),
  requireAuth,
  requireUserFeatureFlag(FLAG_TRAILS),
  async (c) => {
    const userId = requireUserId(c)
    const org = requiredParam(c, "org")
    const repo = requiredParam(c, "repo")
    const repoFullName = `${org}/${repo}`

    const body = await c.req
      .json<{
        runners_enabled?: boolean
        auto_run_on_push?: boolean
      }>()
      .catch(() => null)

    if (!body || (body.runners_enabled === undefined && body.auto_run_on_push === undefined)) {
      return c.json({ error: "At least one setting is required" }, 400)
    }

    // When runners are turned off and auto_run_on_push isn't explicitly set,
    // force it off too — auto-run can't outlive disabled runners.
    const normalizedAutoRunOnPush =
      body.runners_enabled === false && body.auto_run_on_push === undefined
        ? false
        : body.auto_run_on_push

    try {
      const db = getDb(c.env)
      const repoAccess = await requireRepoMembership(db, repoFullName, userId)
      if (repoAccess instanceof Response) return repoAccess

      const nextRunnersEnabled = body.runners_enabled ?? repoAccess.runners_enabled
      const nextAutoRunOnPush = normalizedAutoRunOnPush ?? repoAccess.auto_run_on_push
      if (nextAutoRunOnPush && !nextRunnersEnabled) {
        return c.json({ error: "auto_run_on_push requires runners_enabled" }, 400)
      }

      const settings = {
        runners_enabled: body.runners_enabled,
        auto_run_on_push: normalizedAutoRunOnPush,
      }
      const updatedRepo = await db.repos.updateRunnerSettings(repoAccess.id, settings)

      await mirrorWriteIfEnabled(c, {
        owner: org,
        repo,
        method: "PATCH",
        pathFor: (id) => `repos/${id}/runner-settings`,
        body: JSON.stringify(settings),
      })

      return c.json({
        settings: {
          runners_enabled: updatedRepo.runners_enabled,
          auto_run_on_push: updatedRepo.auto_run_on_push,
        },
      })
    } catch (err) {
      console.error(`Failed to update runner settings for ${repoFullName}:`, err)
      recordSpanError(err)
      return c.json({ error: "Failed to update settings" }, 500)
    }
  },
)

