      "Sets a custom display name for a session. Requires the authenticated " +
      "viewer to have GitHub repo admin permission.",
    responses: {
      200: {
        description: "Updated display name",
        content: { "application/json": { schema: resolver(sessionDisplayNameResponseSchema) } },
      },
      400: {
        description: "Invalid request body or session ID",
        content: { "application/json": { schema: resolver(sessionDisplayNameErrorSchema) } },
      },
      401: {
        description: "GitHub token missing or expired",
        content: { "application/json": { schema: resolver(sessionDisplayNameErrorSchema) } },
      },
      403: {
        description: "Caller is not a repo admin",
        content: { "application/json": { schema: resolver(sessionDisplayNameErrorSchema) } },
      },
      404: {
        description: "Repository or session not found",
        content: { "application/json": { schema: resolver(sessionDisplayNameErrorSchema) } },
      },
    },
  }),
  requireAuth,
  validator("json", sessionDisplayNameRequestSchema, (result, c) => {
    if (!result.success) {
      return c.json({ error: result.error[0].message }, 400)
    }
  }),
  async (c) => {
    const userId = requireUserId(c)
    const org = requiredParam(c, "org")
    const repo = requiredParam(c, "repo")
    const sessionId = requiredParam(c, "sessionId")
    const repoFullName = `${org}/${repo}`

    if (!SESSION_ID_PATTERN.test(sessionId)) {
      return c.json({ error: "Invalid session ID format" }, 400)
    }

    const { displayName } = c.req.valid("json")

    try {
      const db = getDb(c.env)

      const repoAccess = await checkRepoAccess(db, repoFullName, userId, { requireRepo: true })
      if (repoAccess instanceof Response) return repoAccess

      if (!(await hasCheckpointDataAccess(db, repoAccess, userId))) {
        return c.json({ error: CHECKPOINT_REPO_ACCESS_DENIED_ERROR }, 403)
      }

      const tokenResult = await getGitHubTokenViaCore(c)
      if (tokenResult.kind === "reconnect") {
        return c.json({ error: "GitHub reconnect required", reconnect_required: true }, 401)
      }
      if (tokenResult.kind !== "token") {
        return c.json({ error: "GitHub token required" }, 401)
      }

      const { canAdmin } = await checkRepoAdmin({
        kv: c.env.ENTIRE_CACHE,
        userId,
        token: tokenResult.token.accessToken,
        owner: org,
        repo,
      })
      if (!canAdmin) {
        return c.json({ error: "Repo admin required" }, 403)
      }

      // entire-api is the sole store for the session name and owns the
      // existence check — a session missing there returns 404 through the proxy.
      // A local PlanetScale row is no longer required (and would wrongly 404 a
      // session that exists only in entire-api).
      return await proxyEntireApiWrite(c, {
        owner: org,
        repo,
        method: "PATCH",
        pathFor: (id) => `repos/${id}/session/${sessionId}/display-name`,
        body: JSON.stringify({ displayName }),
      })
    } catch (err) {
      if (isGitHubAuthError(err)) {
        return c.json({ error: "GitHub token expired" }, 401)
      }
      console.error(`Failed to update session display name for ${repoFullName}/${sessionId}:`, err)
      recordSpanError(err)
      return c.json({ error: "Failed to update session display name" }, 500)
    }
  },
)

