const RATE_LIMIT_WINDOW_SECONDS = 60
const RATE_LIMIT_MAX_REQUESTS = 60
const AUTH_RATE_LIMIT_WINDOW_SECONDS = 60
const AUTH_RATE_LIMIT_MAX_REQUESTS = 10

async function enforceRateLimit(
  c: Context<{ Bindings: Env; Variables: Variables }>,
  key: string,
  maxRequests: number,
  windowSeconds: number,
): Promise<Response | null> {
  const bucket = Math.floor(Date.now() / 1000 / windowSeconds)
  const bucketKey = `${key}:${bucket}`
  const current = await c.env.ENTIRE_CACHE.get<number>(bucketKey, "json")
  const count = current ?? 0

  if (count >= maxRequests) {
    return c.json({ error: "Rate limit exceeded" }, 429)
  }

  await c.env.ENTIRE_CACHE.put(bucketKey, JSON.stringify(count + 1), {
    expirationTtl: windowSeconds * 2,
  })

  return null
}

export const rateLimitUnauthenticated = createMiddleware<{
  Bindings: Env
  Variables: Variables
}>(async (c, next) => {
  const userId = c.get("userId")
  if (userId) {
    await next()
    return
  }

  const ip = c.req.header("cf-connecting-ip") || "unknown"
  const limited = await enforceRateLimit(
    c,
    `ratelimit:unauth:${ip}`,
    RATE_LIMIT_MAX_REQUESTS,
    RATE_LIMIT_WINDOW_SECONDS,
  )

  if (limited) {
    return limited
  }

  await next()
})

export const rateLimitAuthenticated = createMiddleware<{
  Bindings: Env
  Variables: Variables
}>(async (c, next) => {
  const userId = c.get("userId")
  if (!userId) {
    return c.json({ error: "Not authenticated" }, 401)
  }

  const limited = await enforceRateLimit(
    c,
    `ratelimit:auth:${userId}`,
    AUTH_RATE_LIMIT_MAX_REQUESTS,
    AUTH_RATE_LIMIT_WINDOW_SECONDS,
  )

  if (limited) {
    return limited
  }

  await next()
})

export const requireAuth = createMiddleware<{
  Bindings: Env
  Variables: AuthenticatedVariables
}>(async (c, next) => {
  return requireSessionAuth(c, next)
})

