// /api/v1/me/deletion-preview and /api/v1/me/cancel-deletion are the rest of the
// self-deletion flow and must be exempt for the same reason (exact-path matching,
// so the bare /api/v1/me entry does NOT cover these subpaths). Cancel in
// particular is the only way out of the 7-day cooldown: a pending-deletion
// (cooldown-restricted) session can't pass computeWaitlisted's /userinfo check, so
// without this exemption the waitlist gate would 503 every cancel attempt and trap
// the user. Both are session+CSRF authed and self-scoped, so exempting the
// waitlist check is safe.
//
// Note: /oauth/device/code, /oauth/token, and /api/v1/health are NOT listed
// here. The oauth routes are mounted at app.route("/oauth", ...) — outside
// the /api/v1 session tree — so requireSessionAuth never runs on them.
// /api/v1/health is registered directly on the v1 sub-app without any auth
// middleware, so it likewise never reaches requireSessionAuth. No allowlist
// entries are needed for those paths.
const WAITLIST_ALLOWLIST = new Set<string>([
  "/api/v1/auth/me",
  "/api/v1/auth/logout",
  "/api/v1/me",
  "/api/v1/me/deletion-preview",
  "/api/v1/me/cancel-deletion",
])

export function isWaitlistAllowlisted(path: string): boolean {
  return WAITLIST_ALLOWLIST.has(path)
}

/**
 * Map the waitlist decision for a session request onto a gate response.
 *
 * Short-circuit ordering (cheapest checks first):
 * 1. Path on allowlist → null (no flag/core read).
 * 2. Delegates to computeWaitlisted and maps the 4-state decision:
 *    - "ok"          → null (request proceeds).
 *    - "waitlisted"  → 403 { error: "waitlisted" }.
 *    - "reauth"      → 401 + clear session cookie (the credential is dead).
 *    - "unavailable" → 503 (transient core failure; do NOT waitlist).
 *
 * Fail-closed applies to the FLAG only: an undefined flag ⇒ enforce. Only an
 * explicit PostHog flag=false (e.g. enabled-at-0%) disables the gate. A
 * credential/infra failure is never reported as a waitlist verdict.
 */
async function waitlistGateResponse(
  c: Context<{ Bindings: Env; Variables: Variables }>,
  userId: string,
  sessionToken: string,
): Promise<Response | null> {
  if (isWaitlistAllowlisted(c.req.path)) {
    return null
  }

  const decision = await computeWaitlisted(c.env, userId, sessionToken)

  switch (decision) {
    case "ok":
      return null
    case "waitlisted":
      return c.json({ error: "waitlisted" }, 403)
    case "reauth":
      deleteCookie(c, "session")
      return c.json({ error: "reauth_required" }, 401)
    case "unavailable":
      return c.json({ error: "Authentication service unavailable" }, 503)
    default: {
      // Compile-time exhaustiveness: a new WaitlistDecision arm fails the build
      // here rather than silently falling through and bypassing the gate.
      const _exhaustive: never = decision
      // Runtime fail-safe: if an unexpected value ever reaches this, treat it as
      // a service failure (503) — never return falsy and let the caller proceed.
      void _exhaustive
      return c.json({ error: "Authentication service unavailable" }, 503)
    }
  }
}

async function optionalSessionAuth(
  c: Context<{ Bindings: Env; Variables: Variables }>,
): Promise<void> {
  const sessionToken = getCookie(c, "session")

  if (!sessionToken) {
    return
  }

  try {
    const session = await getSession(c.env.ENTIRE_CACHE, sessionToken)
    if (session) {
      c.set("userId", session.userId)
      // Stamp the account ULID like requireSessionAuth does, so flag eval on
      // optionalAuth routes (e.g. the /commits entire-api gate) keys on
      // the same distinct id as every other authed path instead of the UUID.
      if (session.accountUlid) {
        c.set("accountId", session.accountUlid)
      }
    }
  } catch {
    // KV transient error — degrade to unauthenticated rather than crashing
  }
}

async function requireSessionAuth(
  c: Context<{ Bindings: Env; Variables: Variables }>,
  next: Next,
): Promise<Response | void> {
  const sessionToken = getCookie(c, "session")

  if (!sessionToken) {
    return c.json({ error: "Not authenticated" }, 401)
  }

  const session = await getSession(c.env.ENTIRE_CACHE, sessionToken)

  if (!session) {
    return c.json({ error: "Session expired" }, 401)
  }

  const method = c.req.method
  if ((method === "GET" || method === "HEAD") && !getCookie(c, "csrf")) {
    setCsrfCookie(c)
  }

  if (method === "POST" || method === "PUT" || method === "DELETE" || method === "PATCH") {
    const csrfCookie = getCookie(c, "csrf")
    const csrfHeader = c.req.header("X-CSRF-Token")

    let csrfFailureReason: string | null = null
    if (!csrfCookie && !csrfHeader) {
      csrfFailureReason = "missing_both"
    } else if (!csrfCookie) {
      csrfFailureReason = "missing_cookie"
    } else if (!csrfHeader) {
      csrfFailureReason = "missing_header"
    } else if (!(await timingSafeEqual(csrfCookie, csrfHeader))) {
      csrfFailureReason = "mismatch"
    }

    if (csrfFailureReason) {
      console.log(
        `[csrf] validation_failed`,
        JSON.stringify({
          reason: csrfFailureReason,
          method,
          path: c.req.path,
          userId: session.userId,
        }),
      )
      return c.json({ error: "CSRF token invalid" }, 403)
    }
  }

  c.set("userId", session.userId)
  // Expose the caller's account ULID uniformly for session requests, stamped
  // into the session at login. Absent only for sessions created before this
  // shipped (they self-heal on next login).
  if (session.accountUlid) {
    c.set("accountId", session.accountUlid)
  }

  const gateResponse = await waitlistGateResponse(c, session.userId, sessionToken)
  if (gateResponse) {
    return gateResponse
  }

  await next()
}

export const optionalAuth = createMiddleware<{
  Bindings: Env
  Variables: Variables
}>(async (c, next) => {
  await optionalSessionAuth(c)
  await next()
})

