// Detect whether a repo has at least one checkpoint, so callers can gate
// commit/branch fetching: a repo that has never used the entire CLI shows the
// "install the entire CLI" prompt instead of being synced.
//
// The signal is the presence of the `entire/checkpoints/v1` branch on the
// repo's *effective* checkpoint repo. Checkpoints can live in a separate
// external repo configured in .entire/settings.json
// (strategy_options.checkpoint_remote.repo), so we resolve that first.
//
// Detection is accessibility-first: a bare ref/branch GET returns 404 both when
// the branch is missing AND when the repo is unreadable (e.g. the GitHub App
// isn't installed on an external checkpoint repo). We therefore confirm the
// checkpoint repo is readable before interpreting a missing branch as "absent",
// so the UI can distinguish "install the CLI" (absent) from "authorize the App"
// (inaccessible). Transient failures resolve to "unknown" so callers never
// persist a wrong durable state.

import { CHECKPOINT_BRANCH } from "./constants"
import type { Db } from "./db"
import type { CheckpointBranchState, Repo } from "./db/repos"
import { readEntireSettings, resolveCheckpointRepo } from "./entire-settings"
import { checkBranchExists, getRepoAccessStatus } from "./github"

export interface CheckpointDetectionResult {
  /** Detected state of the checkpoint branch. */
  state: CheckpointBranchState
  /**
   * The resolved effective checkpoint repo (external remote or the repo itself).
   * Null only when it couldn't be resolved (no token, or a transient settings
   * read error) — in that case do NOT persist it as a self-pointer, since a
   * later definite read may reveal an external remote.
   */
  checkpointRepoFullName: string | null
  /**
   * A configured checkpoint remote that was rejected (owner mismatch); mirrors
   * resolveCheckpointRepo. Non-null means we fell back to the repo itself.
   */
  rejectedRemote: string | null
}

const UNRESOLVED: CheckpointDetectionResult = {
  state: "unknown",
  checkpointRepoFullName: null,
  rejectedRemote: null,
}

/**
 * Probe whether `repoFullName` has at least one checkpoint.
 *
 * @param repoFullName  the source/code repo ("owner/name")
 * @param defaultBranch the source repo's default branch (where settings live)
 * @param token         GitHub token able to read the source repo (and, for the
 *                      common self-hosted case, the checkpoint repo)
 */
export async function detectCheckpointBranch(
  repoFullName: string,
  defaultBranch: string,
  token: string | null | undefined,
): Promise<CheckpointDetectionResult> {
  if (!token) return UNRESOLVED

  // Resolve the effective checkpoint repo from .entire/settings.json. Use the
  // throwing reader so we can distinguish "no settings file / not configured"
  // (null -> fall back to self) from a transient fetch error (throw -> unknown,
  // don't persist a self-pointer that would mask a later external remote).
  let settings
  try {
    settings = await readEntireSettings(repoFullName, defaultBranch, token)
  } catch {
    return UNRESOLVED
  }
  const { repo: checkpointRepo, rejectedRemote } = resolveCheckpointRepo(repoFullName, settings)
  const resolved = (state: CheckpointBranchState): CheckpointDetectionResult => ({
    state,
    checkpointRepoFullName: checkpointRepo,
    rejectedRemote,
  })

  // Accessibility-first: confirm we can read the checkpoint repo before treating
  // a missing branch as "absent". Only a definitive 404 ("not_found") means the
  // App can't reach the repo; a transient access failure stays "unknown" so we
  // never persist a wrong durable "inaccessible".
  const [owner, name] = checkpointRepo.split("/")
  if (!owner || !name) return resolved("unknown")
  const access = await getRepoAccessStatus(token, owner, name)
  if (access === "not_found") return resolved("inaccessible")
  if (access === "unknown") return resolved("unknown")

  // Repo is readable, so a 404 on the branch genuinely means "branch missing".
  // checkBranchExists returns null on transient failures; a network throw is
  // likewise transient — both resolve to "unknown".
  let exists: boolean | null
  try {
    exists = await checkBranchExists(checkpointRepo, CHECKPOINT_BRANCH, token)
  } catch {
    exists = null
  }
  return resolved(exists === true ? "present" : exists === false ? "absent" : "unknown")
}

type DetectableRepo = Pick<
  Repo,
  "id" | "full_name" | "default_branch" | "checkpoint_repo_full_name"
>

export interface CheckpointDetectionOutcome {
  /** Detected state — what callers gate on. */
  state: CheckpointBranchState
  /** Resolved effective checkpoint repo, or null if detection couldn't resolve it. */
  checkpointRepoFullName: string | null
  /** Rejected cross-owner remote (mirrors resolveCheckpointRepo); for telemetry. */
  rejectedRemote: string | null
  /** Whether this call changed the persisted checkpoint_repo_full_name. */
  pointerChanged: boolean
}

/**
 * Detect a repo's checkpoint state and persist what we learned. Returns the
 * outcome (state + resolved repo + rejected remote + whether the pointer
 * changed) so callers can gate and emit telemetry.
 *
 * Persistence rules:
 *   - We only write when the checkpoint repo was actually resolved (a real
 *     probe). When detection couldn't resolve it — no token, or a transient
 *     settings-read failure — we persist NOTHING (leaving the repo to be
 *     re-probed later) rather than stamping checked_at on a non-attempt.
 *   - We persist checkpoint_repo_full_name (if it changed) whenever resolved.
 *   - We persist the state only for a DEFINITIVE result (present/absent/
 *     inaccessible). A transient/inconclusive "unknown" is NOT persisted — it
 *     must not overwrite a prior absent/inaccessible, which would silently
 *     un-gate a correctly-gated repo on an API hiccup.
 */
export async function runCheckpointDetection(
  db: Db,
  repo: DetectableRepo,
  token: string | null | undefined,
): Promise<CheckpointDetectionOutcome> {
  const result = await detectCheckpointBranch(repo.full_name, repo.default_branch, token)
  if (result.checkpointRepoFullName === null) {
    return {
      state: result.state,
      checkpointRepoFullName: null,
      rejectedRemote: result.rejectedRemote,
      pointerChanged: false,
    }
  }

  const pointerChanged = result.checkpointRepoFullName !== repo.checkpoint_repo_full_name
  if (pointerChanged) {
    await db.repos.updateCheckpointRepo(repo.id, result.checkpointRepoFullName)
  }
  if (result.state !== "unknown") {
    await db.repos.updateCheckpointBranchState(repo.id, result.state)
  }
  return {
func printCheckpointRemoteHint(target string) {
	if !remote.IsURL(target) {
		return
	}
	fmt.Fprintln(os.Stderr, "[entire] A checkpoint remote is configured in Entire settings (.entire/settings.json or .entire/settings.local.json) but could not be reached.")
	fmt.Fprintln(os.Stderr, "[entire] Checkpoints are saved locally but not synced. Ensure you have access to the checkpoint remote.")
}

// settingsHintOnce ensures the settings commit hint prints at most once per process.
var settingsHintOnce sync.Once

// printSettingsCommitHint prints a hint after a successful checkpoint remote push
// when the committed .entire/settings.json does not contain a checkpoint_remote config.
// entire.io discovers the external checkpoint repo by reading the committed project
// settings, so the checkpoint_remote must be present in HEAD:.entire/settings.json
// (not just in settings.local.json or uncommitted local changes).
// Uses sync.Once to avoid duplicates when multiple branches/refs are pushed in a
// single pre-push invocation.
func printSettingsCommitHint(ctx context.Context, target string) {
	if !remote.IsURL(target) {
		return
	}
	settingsHintOnce.Do(func() {
		if isCheckpointRemoteCommitted(ctx) {
			return
		}
		fmt.Fprintln(os.Stderr, "[entire] Note: Checkpoints were pushed to a separate checkpoint remote, but .entire/settings.json does not contain checkpoint_remote in the latest commit. entire.io will not be able to discover these checkpoints until checkpoint_remote is committed and pushed in .entire/settings.json.")
	})
}

// isCheckpointRemoteCommitted returns true if the committed .entire/settings.json
// at HEAD contains a valid checkpoint_remote configuration. This is the true
// discoverability check: entire.io reads from committed project settings, not from
// local overrides or uncommitted changes.
func isCheckpointRemoteCommitted(ctx context.Context) bool {
	cmd := exec.CommandContext(ctx, "git", "show", "HEAD:.entire/settings.json")
	output, err := cmd.Output()
	if err != nil {
		return false // file doesn't exist at HEAD
	}
	// Parse the committed content and check for checkpoint_remote
	committed, err := settings.LoadFromBytes(output)
	if err != nil {
		return false
	}
	return committed.GetCheckpointRemote() != nil
}

// pushResult describes what happened during a push attempt.
type pushResult struct {
	// upToDate is true when the remote already had all commits (nothing transferred).
	upToDate bool
}

// parsePushResult checks git push --porcelain output for ref status flags.
// In porcelain mode, each ref gets a tab-delimited status line:
//
//	<flag>\t<from>:<to>\t<summary>
//
// where flag '=' means the ref was already up-to-date. This is locale-independent,
// unlike the human-readable "Everything up-to-date" message.
package strategy

import (
	"context"
	"fmt"
	"log/slog"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/remote"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/settings"

	"github.com/go-git/go-git/v6/plumbing"
)

// checkpointRemoteFetchTimeout is the timeout for fetching branches from the checkpoint URL.
const checkpointRemoteFetchTimeout = 30 * time.Second

// pushSettings holds the resolved push configuration from a single settings load.
type pushSettings struct {
	// remote is the git remote name to use for pushing (the user's push remote).
	remote string
	// checkpointURL is the derived URL for pushing checkpoint branches.
	// When set, checkpoint/trails branches are pushed directly to this URL
	// instead of the remote name. Empty means use the remote name.
	checkpointURL string
	// pushDisabled is true if push_sessions is explicitly set to false.
	pushDisabled bool
}

// pushTarget returns the target to use for git push/fetch commands for checkpoint branches.
// If a checkpoint URL is configured, returns that; otherwise returns the remote name.
func (ps *pushSettings) pushTarget() string {
	if ps.checkpointURL != "" {
		return ps.checkpointURL
	}
	return ps.remote
}

// hasCheckpointURL returns true if a dedicated checkpoint URL is configured.
func (ps *pushSettings) hasCheckpointURL() bool {
	return ps.checkpointURL != ""
}

// resolvePushSettings loads settings once and returns the resolved push config.
// If a structured checkpoint_remote is configured (e.g., {"provider": "github", "repo": "org/repo"}):
//   - Derives the checkpoint URL from the push remote's protocol (SSH vs HTTPS)
//   - Skips if the push remote owner differs from the checkpoint repo owner (fork detection)
//   - If a checkpoint branch doesn't exist locally, attempts to fetch it from the URL
//
// The push itself handles failures gracefully (doPushRef warns and continues),
// so no reachability check is needed here.
func resolvePushSettings(ctx context.Context, pushRemoteName string) pushSettings {
	s, err := settings.Load(ctx)
	if err != nil {
		return pushSettings{remote: pushRemoteName}
	}

	ps := pushSettings{
		remote:       pushRemoteName,
		pushDisabled: s.IsPushSessionsDisabled(),
	}

	config := s.GetCheckpointRemote()
	if config == nil {
		return ps
	}
	checkpointURL, enabled, err := remote.PushURL(ctx, pushRemoteName)
	if err != nil {
		logging.Warn(ctx, "checkpoint-remote: could not derive URL from push remote",
			slog.String("remote", pushRemoteName),
			slog.String("repo", config.Repo),
			slog.String("error", err.Error()),
		)
		return ps
	}
	if !enabled || checkpointURL == "" {
		return ps
	}

	ps.checkpointURL = checkpointURL

	// If the v1 checkpoint branch doesn't exist locally, try to fetch it from the URL.
	// This is a one-time operation — once the branch exists locally, subsequent pushes
	// skip the fetch entirely. Only fetch the metadata branch; trails are always pushed
	// to the user's push remote, not the checkpoint remote.
	if err := fetchMetadataBranchIfMissing(ctx, checkpointURL); err != nil {
		logging.Warn(ctx, "checkpoint-remote: failed to fetch metadata branch",
			slog.String("error", err.Error()),
		)
	}

	return ps
}

// FetchMetadataBranch fetches the metadata branch from the checkpoint remote URL
// and updates the local branch. Unlike fetchMetadataBranchIfMissing, this always
// fetches regardless of whether the branch exists locally (for resume scenarios
// where the local branch may be stale).
//
// The fetch is unfiltered (NoFilter: true) because resume needs blob content
// (transcripts, metadata JSON) — not just tree objects.
func FetchMetadataBranch(ctx context.Context, remoteURL string) error {
	refs := checkpoint.ResolveRefs(ctx)
	if !refs.Primary.IsBranch() {
		return fmt.Errorf("primary metadata ref %s is not a branch", refs.Primary)
	}
	branchName := refs.Primary.Short()
	tmpRef := FetchTmpRefPrefix + branchName
	srcRef := refs.Primary.String()

	if err := fetchURLIntoTmpRef(ctx, "", remoteURL, srcRef, tmpRef, "metadata branch", true); err != nil {
		return err
	}
	if err := PromoteTmpRefSafely(ctx, plumbing.ReferenceName(tmpRef), refs.Primary, branchName); err != nil {
		return err
	}

	return nil
}

// fetchURLIntoTmpRef runs `git fetch <remoteURL> +<srcRef>:<tmpRef>` via the
// checkpoint git wrapper, disabling the terminal prompt so a misconfigured
// credential helper doesn't hang the process. Errors include the redacted URL
// and any captured stderr so operators can diagnose without credentials
// leaking into logs.
//
// When noFilter is true, --filter=blob:none is suppressed even if filtered
package strategy

import (
	"context"
	"errors"
	"fmt"
	"io"
	"log/slog"
	"os"
	"os/exec"
	"strings"

	git "github.com/go-git/go-git/v6"
	"github.com/go-git/go-git/v6/plumbing"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/settings"
	"github.com/entireio/cli/perf"
	"github.com/entireio/cli/redact"
)

// errOPFAbortedByUser is returned when the user chose Abort (or pressed
// Ctrl-C) at the OPF prompt. PrePush returns it verbatim; the hook
// command propagates the non-zero exit code so git push aborts.
var errOPFAbortedByUser = errors.New("OPF prompt aborted by user; push cancelled")

var opfPrePushProgressWriter io.Writer = os.Stderr

// PrePush is called by the git pre-push hook before pushing to a remote.
// It pushes each ref in refs.Push alongside the user's push.
//
// If a checkpoint_remote is configured in settings, checkpoint branches/refs
// are pushed to the derived URL instead of the user's push remote.
//
// Configuration options (stored in .entire/settings.json under strategy_options):
//   - push_sessions: false to disable automatic pushing of checkpoints
//   - checkpoint_remote: {"provider": "github", "repo": "org/repo"} to push to a separate repo
func (s *ManualCommitStrategy) PrePush(ctx context.Context, remote string) error {
	return s.prePush(ctx, remote, false)
}

// PrePushFromGitHook handles a push initiated by Git's pre-push hook. Unlike
// direct callers, it protects an empty user remote from receiving checkpoint
// metadata before the user's first normal branch is published.
func (s *ManualCommitStrategy) PrePushFromGitHook(ctx context.Context, remote string) error {
	return s.prePush(ctx, remote, true)
}

func (s *ManualCommitStrategy) prePush(ctx context.Context, remote string, protectFirstUserBranch bool) error {
	// Load settings once for remote resolution and push_sessions check.
	// Spanned because checkpoint-remote resolution can perform a one-time
	// network fetch of the metadata branch (fetchMetadataBranchIfMissing),
	// which is otherwise invisible in the pre-push trace.
	resolveCtx, resolveSpan := perf.Start(ctx, "resolve_push_settings")
	ps := resolvePushSettings(resolveCtx, remote)
	resolveSpan.End()

	if ps.pushDisabled {
		return nil
	}

	// git-refs primary: push the per-checkpoint refs recorded in the push queue
	// instead of the single v1 branch. Those refs live under refs/entire/, not
	// refs/heads/, so a forge can never pick them as a repository's default
	// branch — the empty-remote guard below is unnecessary for this backend.
	// (A configured git-branch mirror's v1 ref is not pushed here yet — mirror
	// push for downgrade safety is a later step.)
