// Process pushes to checkpoint storage refs - stores session metadata (prompt, agent, steps)
export async function processSessionsPushEvent(
  eventType: string,
  payload: Record<string, unknown>,
  db: Db,
  env: Env,
): Promise<void> {
  if (eventType !== "push") return

  const repo = payload.repository as Record<string, unknown> | undefined
  if (!repo?.full_name) return

  const repoFullName = repo.full_name as string
  const ref = payload.ref as string | undefined
  const checkpointSourceRef = getCheckpointSourceRefForPush(ref)

  // Only process pushes to checkpoint refs
  if (!checkpointSourceRef) return

  const deleted = payload.deleted as boolean | undefined
  if (deleted) {
    logCheckpointMetric("sessions_branch_deleted", { repo: repoFullName })
    return
  }

  // Find the global repo record
  // The push may come from a dedicated checkpoint repo, not the code repo itself.
  // Check checkpoint remote first: if this repo is configured as a checkpoint remote
  // for another repo, we must resolve to that source repo. Otherwise, if this repo
  // is also tracked in the repos table (e.g. via installation_repositories webhook),
  // getByGithubId would incorrectly match the checkpoint repo's own record.
  const repoGithubId = repo.id as number
  let repoRecord: Awaited<ReturnType<typeof db.repos.getByGithubId>> = null

  const sourceRepos = await db.repos.getByCheckpointRepoFullName(repoFullName)
  if (sourceRepos.length > 0) {
    logCheckpointMetric("checkpoint_remote_push", {
      checkpointRepo: repoFullName,
      sourceRepoCount: sourceRepos.length,
      sourceRepos: sourceRepos.map((r) => r.full_name),
    })
    // Process for every source repo that uses this checkpoint remote.
    // Each source repo gets its own upsert so checkpoint data lands on the correct record.
    for (const sourceRepo of sourceRepos) {
      await processSessionBranchPushForRepo(sourceRepo, repoFullName, payload, db, env)
    }
    return
  }

  // Not a checkpoint remote — check if this repo itself is tracked
  repoRecord = await db.repos.getByGithubId(repoGithubId)

  if (!repoRecord) {
    logCheckpointMetric("skip_repo_not_found", { repo: repoFullName })
    return
  }

  await processSessionBranchPushForRepo(repoRecord, repoFullName, payload, db, env)
}

