import { CHECKPOINT_BRANCH } from "./constants"

export type CheckpointStorageVersion = number

export const CHECKPOINT_V1_STORAGE_VERSION = 1

export function getCheckpointSourceRefForPush(ref?: string | null): string | null {
  return ref === `refs/heads/${CHECKPOINT_BRANCH}` ? CHECKPOINT_BRANCH : null
}

export function getCheckpointStorageVersionForSourceRef(
  _sourceRef: string,
): CheckpointStorageVersion {
  return CHECKPOINT_V1_STORAGE_VERSION
}

export interface CheckpointTranscriptLocation {
  ref: string
  transcriptFilename: string
  usesUnifiedTranscriptParser: boolean
}

const CHECKPOINT_V1_TRANSCRIPT_LOCATION: CheckpointTranscriptLocation = {
  ref: CHECKPOINT_BRANCH,
  transcriptFilename: "full.jsonl",
  usesUnifiedTranscriptParser: false,
}

export function getCheckpointTranscriptLocation(
  _storageVersion?: CheckpointStorageVersion | null,
): CheckpointTranscriptLocation {
  return CHECKPOINT_V1_TRANSCRIPT_LOCATION
}

export interface CheckpointSyncLocation {
  storageVersion: CheckpointStorageVersion
  sourceRef: string
}

const CHECKPOINT_V1_SYNC_LOCATION: CheckpointSyncLocation = {
  storageVersion: CHECKPOINT_V1_STORAGE_VERSION,
  sourceRef: CHECKPOINT_V1_TRANSCRIPT_LOCATION.ref,
}

/** Default sync location for newly-discovered checkpoints. Always v1. */
export function resolveCheckpointSyncLocation(): CheckpointSyncLocation {
  return CHECKPOINT_V1_SYNC_LOCATION
}
