  const appliedRule = Object.entries(ruleset).find(([rule, condition]) => {
    return condition === true;
  });
  if (appliedRule) {
    const [rule] = appliedRule;
    if (logKey) {
      console.log(`${logKey} rule set to ${rule}`);
    }
    return rule;
  }
  if (logKey) {
    console.log(`${logKey} rule off`);
  }
  return "off";
};

